import math
import sys

def solution(input_data):
    lines = input_data.strip().split('\n')
    parts = list(map(float, lines[0].split()))
    xp, yp, vp = parts[0], parts[1], parts[2]
    parts = list(map(float, lines[1].split()))
    ship_x, ship_y, v, r = parts[0], parts[1], parts[2], parts[3]

    # Planet orbit radius is distance from origin to planet's initial position
    R = math.hypot(xp, yp)
    theta0 = math.atan2(yp, xp)

    def point_distance(p):
        return math.hypot(p[0], p[1])

    def origin_to_segment_distance(a, b):
        """Distance from origin to line segment from a to b."""
        dx, dy = b[0] - a[0], b[1] - a[1]
        mag = math.sqrt(dx*dx + dy*dy)

        if mag < 1e-12:
            return point_distance(a)

        # Perpendicular distance formula
        cross = a[0] * b[1] - a[1] * b[0]
        dist_perp = abs(cross) / mag

        # Check if perpendicular foot lies on segment
        dot = a[0] * dx + a[1] * dy
        if 0 <= dot <= dx*dx + dy*dy:
            return dist_perp

        # Otherwise, closest point is an endpoint
        return min(point_distance(a), point_distance(b))

    def check_valid(t):
        phi = theta0 + vp * t
        planet = (R * math.cos(phi), R * math.sin(phi))

        dist_sp = math.hypot(ship_x - planet[0], ship_y - planet[1])
        if dist_sp > v * t + 1e-9:
            return False

        # Check if path from ship to planet stays outside forbidden zone
        closest = origin_to_segment_distance((ship_x, ship_y), planet)
        return closest >= r - 1e-9

    # First check if initial positions already allow interception at t=0
    if check_valid(0):
        return "0.0000000000\n"

    # Binary search for minimum valid time
    low = 0.0
    high = max(R, R * (v / vp + 1)) + 100000

    for _ in range(200):
        mid = (low + high) / 2
        if check_valid(mid):
            high = mid
        else:
            low = mid

    # Need to ensure we have a valid upper bound, so extend high if needed
    while not check_valid(high) and high < 1e9:
        high *= 2

    for _ in range(200):
        mid = (low + high) / 2
        if check_valid(mid):
            high = mid
        else:
            low = mid

    result = f"{high:.10f}\n"
    return result

