def count_axis_parallel(matrix, n, m):
    count = 0

    for size in range(2, min(n, m) + 1):
        for r in range(n - size + 1):
            for c in range(m - size + 1):
                if is_valid_square(matrix, r, c, size, n, m, 'axis'):
                    count += 1

    return count

def is_valid_square(matrix, r1, c1, size, n, m, orientation):
    # Check if all boundary cells are '1'
    if orientation == 'axis':
        # Check top row
        for c in range(c1, c1 + size):
            if matrix[r1][c] != '1':
                return False
        # Check bottom row
        for c in range(c1, c1 + size):
            if matrix[r1 + size - 1][c] != '1':
                return False
        # Check left column (excluding corners)
        for r in range(r1 + 1, r1 + size - 1):
            if matrix[r][c1] != '1':
                return False
        # Check right column (excluding corners)
