    # Parse input
    lines = input_str.strip().split('\n')
    if n, m_line = lines[0].split():
        n, m = int(n), int(m_line)

    # Parse events and build segments (groups of visits between handle changes)
    segments = []
    current_segment = set()

    for i in range(1, len(lines)):
        line = lines[i].strip()
        if not line:
            continue
        if line == '1':
            if current_segment:
                segments.append(current_segment)
                current_segment = set()
        else:
            parts = line.split()
            if len(parts) >= 2:
                current_segment.add(parts[1])

    if current_segment:
        segments.append(current_segment)

    # If no friends or no segments, max happy friends is 0
    if not segments:
        return "0"

    # Collect all unique friend names
    all_friends = set()
    for seg in segments:
        all_friends.update(seg)

    friends_list = sorted(list(all_friends))
    num_friends = len(friends_list)

    if num_friends == 0:
        return "0"

    # Build conflict adjacency matrix
    # adj[i] is a bitmask where bit j is set if friend i conflicts with friend j
    adj = [0] * num_friends

    for seg in segments:
        seg_indices = [friends_list.index(name) for name in seg]
        for i in seg_indices:
            # Friends i j in same segment can't both be happy
            bitmask = 0
            for j in seg_indices:
                if i != j:
                    bitmask |= (1 << j)
            adj[i] = bitmask

    # Maximum Independent Set using recursive branching with pruning
    best = 0

    def dfs(idx, mask, count):
        nonlocal best

        # If we've processed all nodes, update best
        if idx == num_friends:
            best = max(best, count)
            return

        # Pruning: if remaining nodes + current count can't beat best, skip
        if count + (num_friends - idx) <= best:
            return

        # Option 1: Exclude friend idx, continue to next
        dfs(idx + 1, mask, count)

        # Option 2: Include friend idx if no conflict with already selected
        if (adj[idx] & mask) == 0:
            dfs(idx + 1, mask | (1 << idx), count + 1)

    dfs(0, 0, 0)

    return str(best)

