def solution(input_str):
    n, m = map(int, input_str.split())
    total = n * m

    if total <= 1:
        return "0\n"

    # Build adjacency: each cell connect to itself and valid neighbors (up to 4)
    neighbors = [[] for _ in range(total)]
    for r in range(n):
        for c in range(m):
            idx = r * m + c
            neighbors[idx].append(idx)  # stay in place
            for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    neighbors[idx].append(nr * m + nc)

    # Find minimum dominating set using combinations from smallest size
    def check_dominating(mask):
        """Return True if the set of cells with bits set in mask dominates all cells"""
        for cell in range(total):
            if not (mask & (1 << cell)):
                # Cell is not selected, check if any neighbor is selected
                can_reach = False
                for neighbor in neighbors[cell]:
                    if mask & (1 << neighbor):
                        can_reach = True
                        break
                if not can_reach:
                    return False
        return True

    # Try sizes from 1 to total, find minimum dominating set
    for k in range(1, total + 1):
        for subset in combinations(range(total), k):
            mask = sum(1 << cell for cell in subset)
            if check_dominating(mask):
                # Maximum empty cells = total cells - k occupied cells
                return str(total - k) + "\n"

    # Fallback (should not reach here)
    return "0\n"

