    """Calculate squared distance between two 3D points"""
    return (p1[0]-p2[0])**2 + **(p1[1]-p2[1])2 + (p1[2]-p2[2])**2

def solve_4(p1, p2, p3, p4):
    """Find circumsphere of 4 points (tetrahedron circumcenter)"""
    # Build and solve linear system
    a1 = 2 * (p2[0] - p1[0])
    b1 = 2 * (p2[1] - p1[1])
    c1 = 2 * (p2[2] - p1[2])
    d1 = (p2[0]**2 + p2[1]**2 + p2[2]**2 - p1[0]**2 - p1[1]**2 - p1[2]**2)

    a2 = 2 * (p3[0] - p1[0])
    b2 = 2 * (p3[1] - p1[1])
    c2 = 2 * (p3[2] - p1[2])
    d2 = (p3[0]**2 + p3[1]**2 + p3[2]**2 - p1[0]**2 - p1[1]**2 - p1[2]**2)

    a3 = 2 * (p4[0] - p1[0])
    b3 = 2 * (p4[1] - p1[1])
    c3 = 2 * (p4[2] - p1[2])
    d3 = (p4[0]**2 + p4[1]**2 + p4[2]**2 - p1[0]**2 - p1[1]**2 - p1[2]**2)

    det = a1*(b2*c3 - b3*c2) - b1*(a2*c3 - a3*c2) + c1*(a2*b3 - a3*b2)
    eps = 1e-10

    if abs(det) < eps:
        # Coplanar points - use centroid
        return [(p1[0]+p2[0]+p3[0]+p4[0])/4,
                (p1[1]+p2[1]+p3[1]+p4[1])/4,
                (p1[2]+p2[2]+p3[2]+p4[2])/4]

    x = (d1*(b2*c3 - b3*c2) - d2*(b1*c3 - b3*c1) + d3*(b1*c2 - b2*c1)) / det
    y = (a1*(d2*c3 - d3*c2) - a2*(d1*c3 - d3*c1) + a3*(d1*c2 - d2*c1)) / det
    z = (a1*(d2*b3 - d3*b2) - a2*(d1*b3 - d3*b1) + a3*(d1*b2 - d2*b1)) / det

    return [x, y, z]

