def dp_min_components(component_sizes, target):
    """Find minimum number of components needed to exactly sum to target"""
    if sum(component_sizes) < target:
        return None

    # Dictionary: sum -> minimum component count
    dp = {0: 0}

    for size in component_sizes:
        new_dp = dp.copy()
        for s, count in dp.items():
            if s + size <= target:
                new_s = s + size
                if new_s in dp:
                    new_dp[new_s] = min(new_dp[new_s], count + 1)
                else:
                    new_dp[new_s] = count + 1
        dp = new_dp

    if target in dp:
        return dp[target] - 1  # roads = components - 1
    return None

