    """
    Solution for the grid graph coloring problem.

    The graph has edges between:
    - Horizontal/vertical neighbors
    - Diagonally adjacent cells (forming K4 in each 2x2 subgrid)

    Approach:
    - Even (r+c) positions get colors from {1, 3}
    - Odd (r+c) positions get colors from {2, 4}
    - Use checkerboard pattern to alternate within each parity group
    """
    # Parse input
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:n+1]]

    # First, validate that input has no conflicts
    for r in range(n):
        for c in range(m):
            if grid[r][c] != '0':
                # Check all 8 neighbors
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            if grid[nr][nc] != '0' and grid[r][c] == grid[nr][nc]:
                                return '0'

    # Fill empty cells with checkerboard pattern
    for r in range(n):
        for c in range(m):
            if grid[r][c] == '0':
                if (r + c) % 2 == 0:
                    grid[r][c] = '1'
                else:
                    grid[r][c] = '2'

    # Final validation
    output = '\n'.join(''.join(row) for row in grid)
    return output


