    def concat_all(a, b):
        """Concatenate all numbers from a to b inclusive"""
        if a > b:
            return (0, 0)

        result = 0
        digits = 0
        for i in range(a, b + 1):
            si = str(i)
            d = len(si)
            result = (result * pow_mod10(d) + i) % MOD
            digits += d
