            pos += 1
            right, right_dc = parse_term()
            # Concatenate: val followed by right
            val = (val * pow_mod10(right_dc) + right) % MOD
            dc += right_dc

        return val, dc

    def parse_term():
        nonlocal pos

        # Parse leading number
        start = pos
