            while pos + 1 < n and s[pos + 1].isdigit():
                pos += 1

            end_str = s[end_start:pos]
            if not end_str:
                return (num % MOD, num_digits)

            end = int(end_str)

            if end < num:
                return (0, 0)

            result, dc = concat_all(num, end)
            return (result, dc)

        # Check if '(' means repetition
