    for u, v, w in pre_assigned:
        found.add(make_edge(u, v))

    # Actually, read m lines after first line
    pre = []
    for line in lines[1:m+1]:
        if line:
            u, v, w = map(int, line.split())
            pre.append((u, v, w))
            edge_set.add(make_edge(u, v))

    # Total edges = n*(n-1)/2
    # Pre-assigned edges: m
    # Unassigned: total - m

    # Find unassigned edges by comparing with all possible edges
    all_edges = set()
    for i in range(1, n+1):
        for j in range(i+1, n+1):
