    try:
        n = int(lines[0].strip())
        strings = []
        for i in range(n):
            if i + 1 < len(lines):
                s = lines[i + 1].strip()
                if s:
                    strings.append(s)
    except:
        return "NO\n"

    # Check for critical conflicts
    for i in range(len(strings)):
        for j in range(i + 1, len(strings)):
            if len(strings[i]) == len(strings[j]) and strings[i][0] == strings[j][0]:
                return "NO\n"

    # Verify we have valid strings
    if not strings:
        return "NO\n"

    # Sort lexicographically and concatenate
    strings.sort()
    return "".join(strings) + "\n"

