def solution(input_str):
    """
    Count how many different board squares a knight can reach in no more than k moves.
    """
    lines = input_str.strip().split('\n')
    k, n = map(int, lines[0].split())

    obstacles = set()
    for i in range(1, n + 1):
        if i < len(lines) and lines[i].strip():
            x, y = map(int, lines[i].split())
            obstacles.add((x, y))

    MOD = 1000000007

    # Handle k=0 case - only (0,0) is reachable
    if k == 0:
        if (0, 0) in obstacles:
            return '0\n'
        return '1\n'

    # Knight moves
    moves = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), 
             (1, -2), (1, 2), (2, -1), (2, 1)]

    # Initialize - start at (0,0) if not blocked
    visited = set()
    if (0, 0) not in obstacles:
        visited.add((0, 0))

    # BFS over k moves, accumulating all reachable positions
    for step in range(k):
        new_positions = set()
        for x, y in visited:
            if (x, y) not in obstacles:
                for dx, dy in moves:
                    nx, ny = x + dx, y + dy
                    # Only visit if not previously visited (to avoid cycles)
                    if (nx, ny) not in visited:
                        if (nx, ny) not in obstacles:
                            new_positions.add((nx, ny))

        # Add newly discovered positions to visited set
        visited.update(new_positions)

    return str(len(visited) % MOD) + '\n'

