def solution(input_str):
    n, k, m = map(int, input_str.strip().split())
    MOD = 10**9 + 7

    if k == 1:
        return str(n % MOD)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def count_paths(last, count, visited_mask):
        if count == k:
            return 1
        total = 0
        max_reach = min(last + m, n)
        for next_planet in range(1, max_reach + 1):
            if not (visited_mask & (1 << (next_planet - 1))):
                total = (total + count_paths(next_planet, count + 1, visited_mask | (1 << (next_planet - 1)))) % MOD
        return total

    total_ways = 0
    for start in range(1, n + 1):
        total_ways = (total_ways + count_paths(start, 1, 1 << (start - 1))) % MOD

    return str(total_ways)

